// More faithful simulation: capture the input listener and click listener.
function makePage(store) {
  const listeners = {};
  const note = { value: '' };
  const clear = { addEventListener: (ev, fn) => { listeners['clear:'+ev] = fn; } };
  const localStorage = {
    getItem: k => (k in store ? store[k] : null),
    setItem: (k, v) => { store[k] = String(v); },
  };
  const code = require('fs').readFileSync('/tmp/note-script.js', 'utf8');
  const document = { getElementById: id => (id === 'note' ? note : clear) };
  // expose addEventListener on note too
  note.addEventListener = (ev, fn) => { listeners['note:'+ev] = fn; };
  new Function('localStorage', 'document', code)(localStorage, document);
  return { note, clear, listeners };
}

// 1) First load, empty store
let store = {};
let p = makePage(store);
console.log('1) first load value:', JSON.stringify(p.note.value), '| stored:', JSON.stringify(store['note-text'] ?? null));
if (p.note.value !== '') throw new Error('first load should be empty');

// 2) Type multiline, then "reload" (new page object, same store)
p.note.value = 'line one\nline two';
p.listeners['note:input']();
let p2 = makePage(store);
console.log('2) after reload value:', JSON.stringify(p2.note.value));
if (p2.note.value !== 'line one\nline two') throw new Error('multiline text not preserved');

// 3) Clear, then reload -> stays empty
p2.listeners['clear:click']();
let p3 = makePage(store);
console.log('3) after clear+reload value:', JSON.stringify(p3.note.value), '| stored:', JSON.stringify(store['note-text']));
if (p3.note.value !== '') throw new Error('empty note not preserved');
if (store['note-text'] !== '') throw new Error('empty string not persisted');

// 4) Different browser = different store -> starts empty
let p4 = makePage({});
console.log('4) fresh browser value:', JSON.stringify(p4.note.value));
if (p4.note.value !== '') throw new Error('fresh browser should be empty');

console.log('\nAll persistence checks PASSED');
